**main.py**
```python
from fastapi import FastAPI, WebSocket, WebSocketDisconnect, Cookie, Header, Depends, Path
from fastapi.staticfiles import StaticFiles
from typing import Optional

app = FastAPI()

# Serve static files (HTML, JS, CSS)
app.mount("/static", StaticFiles(directory="static"), name="static")


async def get_cookie_or_client(
    websocket: WebSocket,
    session: Optional[str] = Cookie(None),
    x_client: Optional[str] = Header(None, alias="X-Client"),
) -> Optional[str]:
    """
    Return the value of the `session` cookie or the `X-Client` header.
    If neither is present, return None – do NOT close the connection here.
    """
    return session or x_client


@app.get("/")
async def root():
    """
    Simple HTML entry point – redirects to the static index page.
    """
    return {"detail": "Open /static/index.html in a browser."}


@app.websocket("/items/{item_id}/ws")
async def websocket_endpoint(
    websocket: WebSocket,
    item_id: str = Path(...),
    auth_data: Optional[str] = Depends(get_cookie_or_client),
):
    """
    Echo endpoint.
    Sends a welcome message, then echoes incoming text.
    If authentication data is missing, informs the client.
    """
    await websocket.accept()
    # Inform client about authentication status
    if auth_data is None:
        await websocket.send_text("No authentication data (session cookie or X-Client header) provided.")
    else:
        await websocket.send_text(f"Session Cookie or X-Client Header value is: {auth_data}")

    try:
        while True:
            data = await websocket.receive_text()
            response = (
                f"Message text was: {data}, for item ID: {item_id}"
                if auth_data is None
                else f"Message text was: {data}, for item ID: {item_id}, auth: {auth_data}"
            )
            await websocket.send_text(response)
    except WebSocketDisconnect:
        # Client closed the connection – nothing to do
        pass
```

