```javascript
let ws = null;

// Helper to update UI status
function setStatus(text, error = false) {
    const statusEl = document.getElementById('status');
    statusEl.textContent = text;
    statusEl.style.color = error ? 'red' : 'green';
}

// Append a message to the list
function addMessage(text) {
    const li = document.createElement('li');
    li.textContent = text;
    document.getElementById('messages').appendChild(li);
}

// Called when the "Connect" button is pressed
document.getElementById('connectBtn').addEventListener('click', () => {
    const itemId = document.getElementById('itemId').value.trim();
    if (!itemId) {
        setStatus('Item ID is required', true);
        return;
    }

    // OPTIONAL: set a session cookie so the server receives auth data
    // Comment out the line below if you don't need authentication.
    document.cookie = "session=demo-session-id; path=/";

    const wsUrl = `ws://${location.host}/items/${encodeURIComponent(itemId)}/ws`;
    ws = new WebSocket(wsUrl);

    ws.onopen = () => {
        setStatus('WebSocket connected');
        document.getElementById('sendBtn').disabled = false;
        document.getElementById('closeBtn').disabled = false;
        document.getElementById('msgInput').disabled = false;
    };

    ws.onmessage = (event) => {
        addMessage(`Server: ${event.data}`);
    };

    ws.onerror = (event) => {
        console.error('WebSocket error:', event);
        setStatus('WebSocket error', true);
    };

    ws.onclose = (event) => {
        setStatus(`WebSocket closed (code: ${event.code})`);
        document.getElementById('sendBtn').disabled = true;
        document.getElementById('closeBtn').disabled = true;
        document.getElementById('msgInput').disabled = true;
    };
});

// Send a text message
document.getElementById('sendBtn').addEventListener('click', () => {
    const input = document.getElementById('msgInput');
    const text = input.value.trim();
    if (!text) {
        setStatus('Message cannot be empty', true);
        return;
    }
    ws.send(text);
    addMessage(`You: ${text}`);
    input.value = '';
});

// Close the WebSocket connection
document.getElementById('closeBtn').addEventListener('click', () => {
    ws.close();
});
```

