## 4. Как можно улучшить код (конкретные рекомендации)

### a) `main.py`

```python
import logging
from fastapi import FastAPI, WebSocket, WebSocketDisconnect, Cookie, Header, Depends, Path
from fastapi.responses import RedirectResponse
from fastapi.staticfiles import StaticFiles
from typing import Optional

logger = logging.getLogger("ws_demo")
logging.basicConfig(level=logging.INFO)

app = FastAPI()
app.mount("/static", StaticFiles(directory="static"), name="static")

# ----------------------------------------------------------------------
# Dependency
# ----------------------------------------------------------------------
async def get_cookie_or_client(
    websocket: WebSocket,
    session: Optional[str] = Cookie(None),
    x_client: Optional[str] = Header(None, alias="X-Client"),
) -> Optional[str]:
    """
    Return the value of the `session` cookie or the `X-Client` header.
    If neither is present, simply return ``None`` – the connection stays open.
    """
    return session or x_client


# ----------------------------------------------------------------------
# Routes
# ----------------------------------------------------------------------
@app.get("/", include_in_schema=False)
async def root():
    """Redirect the root URL to the UI page."""
    return RedirectResponse(url="/static/index.html")


@app.websocket("/items/{item_id}/ws")
async def websocket_endpoint(
    websocket: WebSocket,
    item_id: int = Path(..., gt=0),
    auth_data: Optional[str] = Depends(get_cookie_or_client),
):
    """
    Simple echo WebSocket endpoint.
    - Sends a welcome message describing the authentication state.
    - Echoes each received text message.
    """
    await websocket.accept()
    logger.info("WebSocket connection opened for item_id=%s", item_id)

    if auth_data is None:
        await websocket.send_text(
            "No authentication data (session cookie or X-Client header) provided."
        )
    else:
        await websocket.send_text(
            f"Session Cookie or X-Client Header value is: {auth_data}"
        )

    try:
        while True:
            data = await websocket.receive_text()
            logger.info("Received from client: %s", data)
            await websocket.send_text(
                f"Message text was: {data}, for item ID: {item_id}"
            )
    except WebSocketDisconnect:
        logger.info("WebSocket disconnected for item_id=%s", item_id)
    except Exception as exc:  # pragma: no cover
        logger.exception("Unexpected error: %s", exc)
        await websocket.close()
```

